function getMp4Mime(){if(!window.MediaRecorder||!HTMLCanvasElement.prototype.captureStream)return'';return['video/mp4;codecs=avc1.42E01E','video/mp4;codecs=h264','video/mp4'].find(x=>MediaRecorder.isTypeSupported(x))||''}
async function downloadVideo(){const button=$('#videoBtn'),mime=button.dataset.mime||getMp4Mime();if(!mime){button.hidden=true;toast('MP4 video is not supported in this browser.');return}const c=$('#exportCanvas'),stream=c.captureStream(30),chunks=[],rec=new MediaRecorder(stream,{mimeType:mime,videoBitsPerSecond:5000000}),duration=4200,start=performance.now();rec.ondataavailable=e=>{if(e.data.size)chunks.push(e.data)};rec.onerror=()=>{button.hidden=true;button.disabled=false;toast('MP4 export is unavailable here. Use the image download instead.')};rec.onstop=()=>{if(!chunks.length)return;downloadBlob(new Blob(chunks,{type:'video/mp4'}),'my-animated-freak-list.mp4');toast('Your playable MP4 Freak List is ready.')};rec.start(250);button.disabled=true;button.textContent='Creating MP4…';function frame(now){const elapsed=now-start,t=Math.min(1,elapsed/duration);reportFrame(c,t,true);if(t<1)requestAnimationFrame(frame);else{setTimeout(()=>rec.stop(),180);button.disabled=false;button.textContent='Animated MP4'}}requestAnimationFrame(frame)}
let lastEmber=0;
function ambientPointer(e){document.documentElement.style.setProperty('--mx',e.clientX+'px');document.documentElement.style.setProperty('--my',e.clientY+'px');if(state.reducedMotion||matchMedia('(pointer:coarse)').matches||performance.now()-lastEmber<75)return;lastEmber=performance.now();if(Math.random()>.52)return;makeEmber(e.clientX,e.clientY,1)}
function makeEmber(x,y,power=1){const layer=$('#emberLayer');if(!layer)return;const el=document.createElement('i');el.className='ember';el.style.left=x+'px';el.style.top=y+'px';el.style.setProperty('--dx',`${(Math.random()-.5)*70*power}px`);el.style.setProperty('--dy',`${-25-Math.random()*70*power}px`);el.style.width=el.style.height=`${3+Math.random()*4*power}px`;layer.appendChild(el);setTimeout(()=>el.remove(),950)}
function desireBurst(level){if(state.reducedMotion)return;const app=$('#app'),card=$('.card.active'),r=card?.getBoundingClientRect();app.classList.remove('heat-flash');void app.offsetWidth;app.classList.add('heat-flash');setTimeout(()=>app.classList.remove('heat-flash'),800);if(level>=3&&r)for(let i=0;i<level*3;i++)setTimeout(()=>makeEmber(r.left+r.width*(.25+Math.random()*.5),r.top+r.height*(.4+Math.random()*.35),level/2),i*18)}
function bindCardMotion(){const card=$('.card.active');if(!card||state.reducedMotion||matchMedia('(pointer:coarse)').matches)return;card.onpointermove=e=>{const r=card.getBoundingClientRect(),x=(e.clientX-r.left)/r.width-.5,y=(e.clientY-r.top)/r.height-.5;card.style.transform=`perspective(900px) rotateX(${-y*5}deg) rotateY(${x*7}deg) translateY(-3px)`};card.onpointerleave=()=>card.style.transform='translateX(0) rotate(-1.2deg)'}
function panicClear(){if(!confirm('Immediately erase every saved answer from this browser?'))return;localStorage.removeItem('heatcheck-v1');localStorage.removeItem('heatcheck-v2');sessionStorage.removeItem('heatcheck-adult');state.answers={};document.body.innerHTML='<main style="min-height:100vh;display:grid;place-items:center;font-family:system-ui;background:#0b090c;color:#f4efe8"><div style="text-align:center"><h1>Session cleared.</h1><p>No answers remain in this browser.</p><button onclick="location.reload()" style="padding:12px 18px">Start again</button></div></main>'}
function renderAll(){renderCards();updateStats()}
setup();
